import React, { useContext, useReducer, useState } from 'react';
import { UserContext } from '../context/UserContext';
import axios from 'axios';

const estadoInicial = {
    usuario: '',
    contraseña: '',
    nombre: '',
    apellidos: '',
    fecha_nacimiento: '',
};

const reductorFormulario = (estado, accion) => {
    return { ...estado, [accion.campo]: accion.valor };
};

const FormularioUsuario = () => {
    const { agregarUsuario, patronesValidacion } = useContext(UserContext);
    const [estadoFormulario, despachar] = useReducer(reductorFormulario, estadoInicial);
    const [errores, setErrores] = useState([]);

    const manejarCambio = (e) => {
        despachar({ campo: e.target.nombre, valor: e.target.value });
    };

    const validarUsuario = (usuario) => {
        let erroresValidacion = [];

        if (!patronesValidacion.usuario.test(usuario.usuario)) {
            erroresValidacion.push("El nombre de usuario debe tener al menos 6 caracteres, comenzar por una letra y no contener caracteres especiales.");
        }

        if (!patronesValidacion.contraseña.test(usuario.contraseña)) {
            erroresValidacion.push("La contraseña debe tener al menos 8 caracteres, contener una mayúscula y un número.");
        }

        const fecha_nacimiento = new Date(usuario.fecha_nacimiento);
        const hoy = new Date();
        const edad = hoy.getFullYear() - fecha_nacimiento.getFullYear();
        const diferenciaMes = hoy.getMonth() - fecha_nacimiento.getMonth();

        if (edad < 18 || (edad === 18 && diferenciaMes < 0)) {
            erroresValidacion.push("Debes ser mayor de edad (18 años o más).");
        }

        return erroresValidacion;
    };

    const manejarEnvio = async (e) => {
        e.preventDefault();
        setErrores([]); 

        const erroresValidacion = validarUsuario(estadoFormulario);
        if (erroresValidacion.length > 0) {
            setErrores(erroresValidacion);
            return;
        }

        try {
            const respuesta = await axios.post('http://localhost/SERVIDOR/practica/api.php', estadoFormulario);
            agregarUsuario(respuesta.data);
            despachar({ campo: 'reset', valor: estadoInicial }); 
        } catch (error) {
            console.error("Error al agregar el usuario:", error);
            setErrores(["Ocurrió un error al enviar los datos. Intenta nuevamente."]);
        }
    };

    return (
        <form onSubmit={manejarEnvio}>
            {errores.length > 0 && (
                <ul style={{ color: 'red' }}>
                    {errores.map((err, index) => (
                        <li key={index}>{err}</li>
                    ))}
                </ul>
            )}
            <input type="text" nombre="usuario" placeholder="Nombre de usuario" value={estadoFormulario.usuario} onChange={manejarCambio} required />
            <input type="contraseña" nombre="contraseña" placeholder="Contraseña" value={estadoFormulario.contraseña} onChange={manejarCambio} required />
            <input type="text" nombre="nombre" placeholder="Nombre" value={estadoFormulario.nombre} onChange={manejarCambio} required />
            <input type="text" nombre="apellidos" placeholder="Apellidos" value={estadoFormulario.apellidos} onChange={manejarCambio} required />
            <input type="date" nombre="fecha_nacimiento" value={estadoFormulario.fecha_nacimiento} onChange={manejarCambio} required />
            <button type="submit">Agregar Usuario</button>
        </form>
    );
};

export default FormularioUsuario;
